  <script>
    jQuery(document).ready(function($) {

      $('.contact_us_modal_close').on('click', function() {

        var $form = $('.wpcf7 form');

        // Reset all field values
        if ($form.length) {
          $form[0].reset();
        }

        // Remove validation error classes
        $form.find('.wpcf7-not-valid').removeClass('wpcf7-not-valid');

        // Remove validation messages
        $form.find('.wpcf7-not-valid-tip').remove();

        // Hide response message
        $form.find('.wpcf7-response-output').hide().html('');

        // Remove CF7 form states
        //$form.removeClass('invalid failed sent spam aborted');

        // Remove acceptance checked state if needed
        $form.find('.wpcf7-acceptance input').prop('checked', false);

      });

      document.addEventListener('wpcf7mailsent', function() {

        setTimeout(function() {

          $('.wpcf7-response-output')
            .fadeOut(300, function() {
              $(this)
                .removeClass('wpcf7-mail-sent-ok wpcf7-validation-errors wpcf7-spam-blocked')
                .html('')
                .show(); // show again for next submit
            });

        }, 3000);

      });
    });
  </script>


  <script>
    document.addEventListener('DOMContentLoaded', function() {
      var sels = ['section', '.section', 'header', '.card', '.feature', '.tab-pane', '.row > div', 'footer'];
      var seen = new WeakSet();
      sels.forEach(function(s) {
        document.querySelectorAll(s).forEach(function(el) {
          if (seen.has(el)) return;
          seen.add(el);
          el.setAttribute('data-lov-reveal', '');
        });
      });
      var io = new IntersectionObserver(function(entries) {
        entries.forEach(function(e) {
          if (e.isIntersecting) {
            e.target.classList.add('in');
            io.unobserve(e.target);
          }
        });
      }, {
        threshold: 0.08
      });
      document.querySelectorAll('[data-lov-reveal]').forEach(function(el) {
        io.observe(el);
      });
    });
  </script>
  <script>
    document.querySelectorAll('.contact_form_holder').forEach((form) => {
      form.addEventListener('submit', async function(e) {
        e.preventDefault();

        const submitBtn = form.querySelector('button[type="submit"]');
        submitBtn.disabled = true;

        try {
          const response = await fetch(form.action, {
            method: 'POST',
            body: new FormData(form)
          });

          const result = await response.json();

          if (result.status === 'success') {
            Swal.fire({
              icon: 'success',
              title: 'Success',
              text: result.message,
              confirmButtonColor: '#b39648'
            });

            form.reset();

            const modalEl = form.closest('.modal');
            if (modalEl && window.bootstrap) {
              bootstrap.Modal.getInstance(modalEl)?.hide();
            }
          } else {
            Swal.fire({
              icon: 'error',
              title: 'Error',
              text: result.message,
              confirmButtonColor: '#b39648'
            });
          }
        } catch (error) {
          Swal.fire({
            icon: 'error',
            title: 'Error',
            text: 'Something went wrong. Please try again.',
            confirmButtonColor: '#b39648'
          });
        }

        submitBtn.disabled = false;
      });
    });
  </script>
  <script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
